import java.util.ArrayDeque;
import java.util.Deque;

public class QueueStackBenchmarkExample {
    public static void main(String[] args) {
        // Preferred Queue and Stack implementation
        Deque<String> taskQueue = new ArrayDeque<>();

        // Queue operations (FIFO)
        taskQueue.offer("Task-1");
        taskQueue.offer("Task-2");
        String nextTask = taskQueue.poll();

        // Stack operations (LIFO)
        Deque<String> callStack = new ArrayDeque<>();
        callStack.push("Frame-1");
        callStack.push("Frame-2");
        String topFrame = callStack.pop();
    }
}
